SELECT
FROM asts_web_embed_config
is_deleted = 0
AND (config_key ILIKE CONCAT('%', #{keyword}::text, '%') OR config_name ILIKE CONCAT('%', #{keyword}::text, '%'))
AND is_enabled = #{isEnabled}
ORDER BY id DESC LIMIT #{limit} OFFSET #{offset}

SELECT COUNT(*)
FROM asts_web_embed_config
WHERE config_key = #{configKey}
AND is_deleted = 0

    AND id != #{excludeId}
